4	import org.junit.jupiter.api.DisplayName;
5	import org.junit.jupiter.api.Test;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
8	import org.springframework.boot.jpa.test.autoconfigure.TestEntityManager;
9	import org.springframework.boot.persistence.autoconfigure.EntityScan;
10	import org.springframework.test.context.TestPropertySource;
11	
12	import java.util.List;
13	
14	import static org.assertj.core.api.Assertions.assertThat;
15	
16	/**
17	 * One {@link Money} flattens to two columns, and the currency is a {@code varchar} holding
18	 * the currency's <em>name</em> rather than its ordinal.
19	 *
20	 * <p>The name is not the default: an enum JPA is given no instruction about is stored by
21	 * <b>ordinal</b>, so reordering {@link Currency}'s constants would silently reinterpret
22	 * every row already written. What this test pins is that {@code Money} carries an
23	 * instruction at all — strip both of its currency annotations and the context fails to
24	 * start, because Hibernate then expects a {@code tinyint} where the migration wrote a
25	 * {@code varchar}. Design decision 29 has the full mapping story and why both annotations
26	 * stay.
27	 *
28	 * <p>The arrangement is the application's own rather than a JPA test's usual one: the table
29	 * comes from a migration and Hibernate runs on {@code validate}, exactly as ticket 08's
30	 * accounts table will. Checking the mapping <em>against hand-written SQL</em> is what makes
31	 * a startup failure the assertion, and it rehearses the position ticket 08 writes its
32	 * migration from.
33	 */
34	@DataJpaTest
35	@EntityScan(basePackageClasses = MoneyEmbeddingHost.class)
36	@TestPropertySource(properties = {
37			// The host entity is test-only, so its table ships beside this test rather than
38			// in db/migration, which Flyway owns for the schema the application runs on.
39			"spring.flyway.locations=classpath:db/testmigration/moneymapping",
40			// The application's own setting, restated because the claim below rests on it.
41			"spring.jpa.hibernate.ddl-auto=validate"
42	})
43	class MoneyMapsToTwoColumnsTest {
44	
45		@Autowired
46		private TestEntityManager entityManager;
47	
48		/**
49		 * Startup is half the assertion: {@code validate} has already compared the mapping
50		 * against the migration by the time this method runs. The body confirms the agreement
51		 * is a working one and not merely a nominal one.
52		 */
53		@Test
54		@DisplayName("the mapping agrees with a hand-written varchar column, and money round trips through it")
55		void roundTripsThroughAHandWrittenSchema() {
56			Money amount = new Money(123_45L, Currency.EUR);
57	
58			Long id = entityManager.persistAndGetId(new MoneyEmbeddingHost(amount), Long.class);
59			entityManager.flush();
60			entityManager.clear();
61	
62			assertThat(entityManager.find(MoneyEmbeddingHost.class, id).getAmount()).isEqualTo(amount);
63		}
64	
65		/**
66		 * Read in SQL rather than through Hibernate, so this asserts what is in the database
67		 * rather than what the mapping is willing to say about it — a round trip through the
68		 * same mapping would agree with itself whatever it wrote.
69		 *
70		 * <p>Note what the implicit naming strategy does <em>not</em> do — the host's field is
71		 * called {@code amount} and no column is named after it. An entity carrying two Money
72		 * figures therefore needs {@code @AttributeOverride} to keep them apart, which is
73		 * ticket 08's first job.
74		 */
75		@Test
76		@DisplayName("the count and the currency are stored as minor_units and a currency name")
77		void storesTheCountAndTheCurrencyName() {
78			entityManager.persistAndFlush(new MoneyEmbeddingHost(new Money(-150L, Currency.HUF)));
79			entityManager.clear();
80	
81			@SuppressWarnings("unchecked")
82			List<Object[]> rows = entityManager.getEntityManager()
83					.createNativeQuery("SELECT minor_units, currency FROM money_embedding_host")
84					.getResultList();
85	
86			assertThat(rows).hasSize(1);
87			assertThat(((Number) rows.getFirst()[0]).longValue()).isEqualTo(-150L);
88			assertThat(rows.getFirst()[1]).hasToString("HUF");
89		}
90	}
