1	package hu.bankmonitor.payments;
2	
3	import hu.bankmonitor.payments.common.ProblemType;
4	import hu.bankmonitor.testsupport.ProblemProbeController;
5	import org.junit.jupiter.api.DisplayName;
6	import org.junit.jupiter.api.Nested;
7	import org.junit.jupiter.api.Test;
8	import org.springframework.beans.factory.annotation.Autowired;
9	import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
10	import org.springframework.context.annotation.Import;
11	import org.springframework.http.HttpHeaders;
12	import org.springframework.http.MediaType;
13	import org.springframework.test.web.servlet.assertj.MockMvcTester;
14	import org.springframework.test.web.servlet.assertj.MvcTestResult;
15	
16	import static org.assertj.core.api.Assertions.assertThat;
17	import static org.assertj.core.api.InstanceOfAssertFactories.LIST;
18	
19	/**
20	 * The one error format, asserted at the web layer with no database behind it.
21	 *
22	 * <p>Every test states the {@code type} URN, because that URN is the only field a client
23	 * is allowed to branch on (design decision 18). The shape assertions are here for the
24	 * same reason: a caller that has parsed one problem document has parsed all of them, so
25	 * a failure the framework raises before any of our code runs has to be
26	 * indistinguishable, in shape, from one a slice raises deliberately.
27	 *
28	 * <p>{@code @WebMvcTest} rather than a booted application: nothing here touches
29	 * persistence, and the contract belongs to the dispatcher and the exception handler in
30	 * front of it.
31	 */
32	@WebMvcTest
33	@Import({SecurityConfiguration.class, ProblemProbeController.class})
34	class ProblemDocumentContractTest {
35	
36		@Autowired
37		private MockMvcTester mvc;
38	
39		@Test
40		@DisplayName("a validation failure reports one entry per rejected field")
41		void validationFailureReportsOneEntryPerRejectedField() {
42			MvcTestResult result = mvc.post().uri(ProblemProbeController.PATH)
43					.contentType(MediaType.APPLICATION_JSON)
44					.content("""
45							{"reference": "", "weight": -1}""")
46					.exchange();
47	
48			assertThat(result).hasStatus(400);
49			assertThatIsAProblemDocument(result, ProblemType.VALIDATION_FAILED);
50			assertThat(result).bodyJson()
51					.extractingPath("$.errors[*].field").asInstanceOf(LIST)
52					.containsExactly("reference", "weight");
53			assertThat(result).bodyJson()
54					.extractingPath("$.errors[?(@.field == 'reference')].message")
55					.asInstanceOf(LIST)
56					.isNotEmpty();
57		}
58	
59		/**
60		 * A constraint on a query parameter, a path variable or a header is a different
61		 * exception inside Spring. If only the body case carried the extension member, the
62		 * document's shape would depend on where the rejected value arrived — a distinction
63		 * the client cannot see and cannot branch on.
64		 */
65		@Test
66		@DisplayName("a rejected parameter reports its field too, not only a rejected body")
67		void rejectedParameterReportsItsFieldToo() {
68			MvcTestResult result = mvc.get()
69					.uri(ProblemProbeController.PATH + ProblemProbeController.CONSTRAINED_PARAMETER)
70					.param("pageSize", "-1")
71					.exchange();
72	
73			assertThat(result).hasStatus(400);
74			assertThatIsAProblemDocument(result, ProblemType.VALIDATION_FAILED);
75			assertThat(result).bodyJson()
76					.extractingPath("$.errors[*].field").asInstanceOf(LIST)
77					.containsExactly("pageSize");
78		}
79	
80		/**
81		 * The default packs every violation into one sentence in {@code detail}. A form that
82		 * has to mark up the offending input cannot read that, which is the whole reason for
83		 * the extension member above — so the member has to be there even when a single field
84		 * is wrong.
85		 */
86		@Test
87		@DisplayName("a single violation is still reported as a field entry")
88		void singleViolationIsStillReportedAsAFieldEntry() {
89			MvcTestResult result = mvc.post().uri(ProblemProbeController.PATH)
90					.contentType(MediaType.APPLICATION_JSON)
91					.content("""
92							{"reference": "ok", "weight": -1}""")
93					.exchange();
94	
95			assertThat(result).bodyJson()
96					.extractingPath("$.errors[*].field").asInstanceOf(LIST)
97					.containsExactly("weight");
98		}
99	
100		@Test
101		@DisplayName("malformed JSON is a problem document")
102		void malformedJsonIsAProblemDocument() {
103			MvcTestResult result = mvc.post().uri(ProblemProbeController.PATH)
104					.contentType(MediaType.APPLICATION_JSON)
105					.content("{ not json")
106					.exchange();
107	
108			assertThat(result).hasStatus(400);
109			assertThatIsAProblemDocument(result, ProblemType.MALFORMED_REQUEST);
110		}
111	
112		@Test
113		@DisplayName("an unsupported media type is a problem document")
114		void unsupportedMediaTypeIsAProblemDocument() {
115			MvcTestResult result = mvc.post().uri(ProblemProbeController.PATH)
